async function startSessionApiServer(
  sessionId: string,
  capabilities: SessionCapabilities,
): Promise<SessionControlEndpoint | undefined> {
  if (
    !(capabilities.observe || capabilities.control || capabilities.interact)
  ) {
    return undefined;
  }

  await stopSessionApiServer();

  const socketPath = getSocketPath(sessionId);
  const authToken = crypto.randomBytes(24).toString("hex");
  if (process.platform !== "win32") {
    await fs.mkdir(path.dirname(socketPath), { recursive: true });
    await fs.unlink(socketPath).catch(() => {});
  }

  const server = net.createServer((socket) => {
    socket.setEncoding("utf8");
    let buffer = "";
    let requestQueue = Promise.resolve();

    socket.on("data", (chunk: string) => {
      buffer += chunk;
      let newlineIndex = buffer.indexOf("\n");
      while (newlineIndex >= 0) {
        const rawLine = buffer.slice(0, newlineIndex).trim();
        buffer = buffer.slice(newlineIndex + 1);
        newlineIndex = buffer.indexOf("\n");

        if (!rawLine) {
          continue;
        }

        requestQueue = requestQueue
          .then(async () => {
            let request: SessionApiRequest;
            try {
              request = JSON.parse(rawLine) as SessionApiRequest;
            } catch {
              const response: SessionApiResponse = {
                ok: false,
                error: "invalid json request",
              };
              socket.write(`${JSON.stringify(response)}\n`);
              return;
            }

            const response = await handleSessionApiRequest(request);
            socket.write(`${JSON.stringify(response)}\n`);
          })
          .catch(() => {});
      }
    });
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(socketPath, () => {
      server.off("error", reject);
      resolve();
    });
  });

  sessionApiServer = server;
  sessionApiSocketPath = socketPath;
  sessionApiAuthToken = authToken;

  return {
    transport: process.platform === "win32" ? "tcp" : "unix",
    address: socketPath,
    version: "v1",
    auth_token: authToken,
  };
}

function registerExitHandlers(): void {
  if (exitHandlersRegistered) return;
  exitHandlersRegistered = true;

  const cleanup = async () => {
    if (!registeredSessionId) return;
    await stopSessionApiServer();
    await removeSession(registeredSessionId);
  };

  process.on("exit", () => {
    void cleanup();
  });
  process.on("SIGINT", () => {
    void cleanup().finally(() => process.exit(0));
  });
  process.on("SIGTERM", () => {
    void cleanup().finally(() => process.exit(0));
  });
}

