let sessionControlHandlers: SessionControlHandlers = {};

type SessionApiMethod =
  | "session.get_status"
  | "session.get_health"
  | "session.get_context_summary"
  | "session.get_recent_history"
  | "session.cancel_turn"
  | "session.restart_turn"
  | "session.pause"
  | "session.resume"
  | "session.set_model"
  | "session.set_approval_mode"
  | "session.shutdown"
  | "session.request_self_repair";

interface SessionApiRequest {
  id?: string | number;
  method?: SessionApiMethod;
  auth_token?: string;
  params?: Record<string, unknown>;
}

interface SessionApiResponse {
  id?: string | number;
  ok: boolean;
  result?: unknown;
  error?: string;
}

function requiresAuthToken(method: SessionApiMethod): boolean {
  switch (method) {
    case "session.get_status":
    case "session.get_health":
    case "session.get_context_summary":
    case "session.get_recent_history":
    case "session.cancel_turn":
    case "session.restart_turn":
    case "session.pause":
    case "session.resume":
    case "session.set_model":
    case "session.set_approval_mode":
    case "session.shutdown":
    case "session.request_self_repair":
      return true;
    default:
      return false;
  }
}

function makeActionResult(result: {
  accepted: boolean;
  reason?: string;
  action_id?: string;
}): {
  accepted: boolean;
  reason?: string;
  action_id: string;
} {
  return {
    accepted: result.accepted,
    reason: result.reason,
    action_id: result.action_id ?? `action-${Date.now()}`,
  };
}

function normalizeControlHandlerResult(
  value: boolean | SessionControlHandlerResult | undefined,
): {
  accepted: boolean;
  reason?: string;
} {
  if (typeof value === "boolean") {
    return {
      accepted: value,
      reason: value ? undefined : "handler_rejected",
    };
  }
  if (
    value &&
    typeof value === "object" &&
    typeof value.accepted === "boolean"
  ) {
    return {
      accepted: value.accepted,
      reason: value.reason,
    };
  }
  return {
    accepted: false,
    reason: "invalid_handler_result",
  };
}

