async function callUnixSessionApi(
  socketPath: string,
  method: string,
  authToken?: string,
  params?: Record<string, unknown>,
): Promise<SessionApiEnvelope | null> {
  return await new Promise<SessionApiEnvelope | null>((resolve) => {
    const request = {
      id: `orchestrator-${Date.now()}`,
      method,
      auth_token: authToken,
      params,
    };

    let resolved = false;
    let buffer = "";
    const socket = net.createConnection({ path: socketPath });
    const timeout = setTimeout(() => {
      if (!resolved) {
        resolved = true;
        socket.destroy();
        resolve(null);
      }
    }, 1500);

    const finish = (value: SessionApiEnvelope | null) => {
      if (resolved) {
        return;
      }
      resolved = true;
      clearTimeout(timeout);
      socket.destroy();
      resolve(value);
    };

    socket.on("connect", () => {
      socket.write(`${JSON.stringify(request)}\n`);
    });

    socket.on("data", (chunk: Buffer | string) => {
      buffer += chunk.toString();
      const newlineIndex = buffer.indexOf("\n");
      if (newlineIndex < 0) {
        return;
      }

      const line = buffer.slice(0, newlineIndex).trim();
      if (!line) {
        finish(null);
        return;
      }

      try {
        finish(JSON.parse(line) as SessionApiEnvelope);
      } catch {
        finish(null);
      }
    });

    socket.on("error", () => finish(null));
    socket.on("end", () => finish(null));
    socket.on("close", () => finish(null));
  });
}

