const net = require('net');

// Send a request to the TUI session API
function callSessionApi(socketPath, method, authToken, params) {
  return new Promise((resolve) => {
    const request = {
      id: Date.now(),
      method,
      auth_token: authToken,
      params
    };

    let buffer = '';
    let resolved = false;

    const socket = net.createConnection({ path: socketPath });

    const timeout = setTimeout(() => {
      if (!resolved) {
        resolved = true;
        socket.destroy();
        resolve(null);
      }
    }, 5000);

    socket.on('connect', () => {
      console.log('Connected to session API');
      socket.write(JSON.stringify(request) + '\\n');
    });

    socket.on('data', (chunk) => {
      buffer += chunk.toString();
      const newlineIndex = buffer.indexOf('\\n');
      if (newlineIndex >= 0) {
        const line = buffer.slice(0, newlineIndex).trim();
        try {
          const response = JSON.parse(line);
          console.log('Response:', JSON.stringify(response, null, 2));
          resolved = true;
          socket.destroy();
          resolve(response);
        } catch (e) {
          console.log('Parse error:', e.message);
        }
      }
    });

    socket.on('error', () => {
      if (!resolved) {
        resolved = true;
        resolve(null);
      }
    });
  });
}

async function test() {
  const sessionData = require('/home/atmandk/.qwen/sessions.json');
  const tuiSession = sessionData.sessions.find(s => s.mode === 'tui');

  if (!tuiSession) {
